import AppKit
import SwiftUI

public struct AppLogo {
    public static let base64Data = ""
    
    public static var nsImage: NSImage {
        if let data = Data(base64Encoded: base64Data), let img = NSImage(data: data) {
            return img
        }
        return NSImage(systemSymbolName: "character.book.closed.fill", accessibilityDescription: "ToolTrL") ?? NSImage()
    }
    
    public static var image: Image {
        Image(nsImage: nsImage)
    }
}